INSERT INTO `trinity_string` (`entry`, `content_default`, `content_loc2`) VALUES
(600300, 'Who farted?!', 'Qui a pété ?!'),
(600301, 'Ugh! It smells like rotten eggs!', 'Pouah ! Ça sent l''œuf pourri !'),
(600302, 'It wasn''t me, I swear!', 'C''est pas moi, je le jure !'),
(600303, 'My eyes! My poor eyes are watering!', 'Mes yeux ! Mes pauvres yeux qui piquent !'),
(600304, 'Somebody forgot to wash their feet again...', 'Quelqu''un a encore oublié de se laver les pieds...'),
(600306, 'Hold your breath! Everybody hold your breath!', 'Retenez votre souffle ! Tout le monde retient son souffle !'),
(600307, 'Yuck! Who opened the cheese crate?', 'Beurk ! Qui a ouvert la caisse de fromage ?'),
(600309, 'Hey! You up there on the broom! Come back here!', 'Hé ! Toi, là-haut, sur ton balai ! Reviens ici !'),
(600312, 'Mommy, it stinks!', 'Maman, ça pue !'),
(600313, 'A curse of eternal flatulence? Lovely atmosphere.', 'Un sortilège de flatulence éternelle ? Sympa l''ambiance.'),
(600314, 'Oops... I don''t think that was just a toot.', 'Oups... Je crois que c''était pas juste un prout.'),
(600315, 'Whoa, that smells like a big warm poop!', 'Oula, ça sent le gros caca bien chaud !'),
(600316, 'Holy cow, somebody change that kid''s diaper!', 'Oh la vache, changez la couche du petit là !'),
(600317, '*sniff* Oh, right... There''s a corpse in the room, isn''t there?', '*snif* Ah ouais d''accord... Il y a un cadavre dans la pièce en fait.'),
(600318, 'Ugh... That smells like a really runny poop.', 'Oula... Ça sent le caca bien mou.'),
(600319, 'Honestly, whoever did that needs to see a doctor.', 'Franchement, le mec qui a fait ça doit consulter un médecin.'),
(600320, 'That smells like a big greasy fart, it''s disgusting.', 'Ça sent le gros prout bien gras, c''est infect.'),
(600321, 'Something has rotted in somebody''s underpants...', 'Il y a un truc qui a pourri dans la culotte de quelqu''un...'),
(600322, 'Oh, the horror... That''s a competition-grade fart.', 'Oh l''angoisse... C''est un prout de compétition ça.'),
(600323, 'Wait... is that smell coming from me?', 'C''est moi qui pue comme ça ?'),
(600340, 'Ugh! What did you just let rip?!', 'Pouah ! Mais tu as lâché quoi là ?!'),
(600341, 'That''s nature, let it express itself!', 'C''est la nature, laisse-la s''exprimer !'),
(600342, 'I tasted your smell without meaning to...', 'J''ai goûté ton odeur sans le vouloir...'),
(600343, 'So? Is it well seasoned at least?', 'Et alors ? C''est bien assaisonné au moins ?'),
(600344, 'What on earth did you leave to marinate under that broom?!', 'Mais vous avez fait macérer quoi sous votre balai ?!'),
(600345, 'It''s granny''s secret recipe, hands off!', 'C''est la recette secrète de mamie, touche pas à ça !'),
(600346, 'My nose just literally melted onto the floor!', 'Mon nez vient littéralement de fondre par terre !'),
(600347, 'Well, you weren''t using it anyway!', 'De toute façon, il te servait à rien !'),
(600348, 'Honestly, even a dead rat would file a complaint!', 'Franchement, même un rat crevé porterait plainte !'),
(600349, 'The rat didn''t say a thing, don''t you go snitching!', 'Le rat a rien dit du tout, commence pas à balancer !'),
(600350, 'That''s not a smell anymore, that''s an assault!', 'C''est pas une odeur à ce stade, c''est une agression !'),
(600351, 'I plead not guilty, it was an accident!', 'Je plaide non coupable, c''était un accident !'),
(600352, 'My nostrils are burning from the inside!', 'Mes narines sont en train de brûler de l''intérieur !'),
(600353, 'Liar, you don''t even have a nose anymore.', 'Menteur, t''as même plus de nez.'),
(600354, 'You smell like you forgot to wash since 1845!', 'On dirait que tu as oublié de te laver depuis 1845 !'),
(600355, 'I''m preserving my microbiome, respect my choices!', 'Je préserve mon microbiote, respecte mes choix !'),
(600356, 'You smell like the bottom of a bin left out in the sun!', 'Tu sens le fond de poubelle au soleil !'),
(600357, 'It''s vintage, it''s very trendy!', 'C''est vintage, c''est très à la mode !'),
(600358, 'What on earth happened in your pants?!', 'Mais qu''est-ce qui s''est passé dans ton slip ?!'),
(600359, 'That''s confidential, it''s between me and my doctor!', 'C''est confidentiel, ça regarde que moi et mon médecin !'),
(600331, 'Ugh! What kind of monster laid that one?', 'Pouah ! C''est quel genre de monstre qui a pondu ça ?'),
(600330, 'And they say WE smell like death!', 'Et on dit que c''est NOUS qui sentons le mort !');
